#!/usr/bin/env python3
"""Write ``AutoGenerated/core_paper.json``: the core paper manifest (D-025).

Reads ``PM/paper/core_manifest.CORE_MANIFEST`` and ``sections.json``. Lists the
core sections in manifest order with their role sentence and word count, the
supplementary sections, and totals. Fails early if a manifest id is missing
from sections.json.

Run: ``python -m metaphysica.generators.generate_core_paper``

Copyright (c) 2025-2026 Andrew Keith Watts. All rights reserved.
"""
from __future__ import annotations

import json
import re
import sys
from typing import Any, Dict, List

from metaphysica.generators._common import autogen_dir, write_json_stable
from metaphysica.simulations.PM.paper.core_manifest import CORE_MANIFEST

_SKIP_KEYS = {"type", "label", "id", "formula_id", "callout_type",
              "formula_refs", "param_refs"}


def _strings(value: Any) -> List[str]:
    if isinstance(value, str):
        return [value]
    if isinstance(value, list):
        return [s for v in value for s in _strings(v)]
    if isinstance(value, dict):
        return [s for k, v in value.items() if k not in _SKIP_KEYS
                for s in _strings(v)]
    return []


def section_words(entry: Dict[str, Any]) -> int:
    """Words in a section's content blocks after stripping tags."""
    text = " ".join(_strings(entry.get("content_blocks", [])))
    return len(re.sub(r"<[^>]+>", " ", text).split())


def build(sections: Dict[str, Any]) -> Dict[str, Any]:
    """The core_paper payload; raises if a manifest id is not a section."""
    missing = [sid for sid, _ in CORE_MANIFEST if sid not in sections]
    if missing:
        raise SystemExit("generate_core_paper: manifest ids missing from "
                         "sections.json: %s" % ", ".join(missing))
    core = [{"id": sid, "title": sections[sid].get("title", sid),
             "role": role, "words": section_words(sections[sid])}
            for sid, role in CORE_MANIFEST]
    core_ids = {c["id"] for c in core}
    supp = [{"id": sid, "title": e.get("title", sid),
             "words": section_words(e)}
            for sid, e in sections.items() if sid not in core_ids]
    core_w = sum(c["words"] for c in core)
    supp_w = sum(s["words"] for s in supp)
    return {"version": 1, "core": core, "supplementary": supp,
            "totals": {"core_sections": len(core), "core_words": core_w,
                       "supplementary_sections": len(supp),
                       "supplementary_words": supp_w,
                       "all_sections": len(core) + len(supp),
                       "all_words": core_w + supp_w}}


def main() -> int:
    path = autogen_dir() / "sections.json"
    if not path.is_file():
        raise SystemExit("generate_core_paper: %s is missing; run 'Run all "
                         "simulations' first." % path)
    sections = json.loads(path.read_text(encoding="utf-8"))["sections"]
    payload = build(sections)
    write_json_stable(autogen_dir() / "core_paper.json", payload)
    t = payload["totals"]
    print("generate_core_paper: %d core sections, %d words of %d" % (
        t["core_sections"], t["core_words"], t["all_words"]))
    return 0


if __name__ == "__main__":
    sys.exit(main())
